import{_ as r,o as a,c as o,ae as t}from"./chunks/framework.Iv6F95cJ.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/arch-from-zero/致「从0开始学架构」专栏订阅用户.md","filePath":"books/arch-from-zero/致「从0开始学架构」专栏订阅用户.md"}'),_={name:"books/arch-from-zero/致「从0开始学架构」专栏订阅用户.md"};function n(p,e,c,s,i,g){return a(),o("div",null,[...e[0]||(e[0]=[t('<p>你好，我是华仔。在我的专栏结束后，<strong>今天又有一个好消息想分享给你，而且这件事情离不开每位订阅专栏同学的支持。</strong></p><p>事情的源起是「从0开始学架构」专栏发布时，我在InfoQ公众号文章的一条留言。</p><p><img src="https://static001.geekbang.org/resource/image/74/6b/740c2af41e4c203452e1cca3764c1b6b.jpg?wh=987%2A290" alt="" loading="lazy" referrerpolicy="no-referrer"></p><p>由于我一直有不定期捐助“免费午餐”的习惯，当时就想正好借此机会，完成一个小小的愿望：在专栏结束后，按照订阅人数，捐出同等数量的免费午餐。</p><p>9月，在专栏结束后，有26000人订阅了我的专栏，而我也兑现了当初的承诺，捐出了26000份免费午餐，耒阳市导子镇上古小学（<a href="https://m.weibo.cn/u/6478785428?from=1089395010&amp;wm=9006_2001&amp;sourceType=weixin&amp;uid=2058877932" target="_blank" rel="noreferrer">微博</a>）的100个孩子可以放心吃上1年。</p><p><img src="https://static001.geekbang.org/resource/image/99/a8/99c5cf7ffbc1abb17a5393d4404f7aa8.jpeg?wh=1440%2A1080" alt="" loading="lazy" referrerpolicy="no-referrer"><br><img src="https://static001.geekbang.org/resource/image/91/e0/912ad45ddf78ca313ce1f3299041a6e0.jpg?wh=690%2A920" alt="" loading="lazy" referrerpolicy="no-referrer"></p><p>正如我当初立下的一个小小的flag：让技术既改变自己，也惠泽他人。通过专栏，我们一起学习进步，又一起完成100个孩子1年免费午餐的捐助，当初立下的flag算是完美达成。<strong>我代表孩子们感谢订阅了专栏的你，也祝愿孩子们健康快乐成长，长大后成为优秀的架构师 ：）</strong> 精选留言（15） 王刚 👍（32） 💬（1）你做了我想做而现在暂时还做不到的事，真心羡慕和佩服你！比你有钱的人很多，但是你能在自己的能力范围内帮助别人，这是一种修行，一种境界！向你致敬！！！不仅从您的专栏学到了技术，还学到了技术以外的东西～希望您以后多出些专栏！我一定继续支持您！！！2018-10-10一一 👍（5） 💬（1）一年以后呢……2018-10-10KuangXiang 👍（4） 💬（1）不错，孩子们替我多吃点，华仔👌 2018-10-10lyonger 👍（3） 💬（1）好赞啊，这篇文章在专栏的介绍里应该置顶和提及。给华哥点赞👍2020-03-29王子瑞Aliloke有事电联 👍（3） 💬（1）感谢华仔，在这里开拓了视野，学到了知识，也感受到了知识之外的感动-- 被你那句“让技术既改变自己，也惠泽他人”深深感动。 今后我也会践行你那句话。再次感谢！ 2019-03-08happyzeng 👍（2） 💬（1）华仔很赞，谢谢您这有爱心，有温度的善行。相信这句”技术不仅改变自己，还惠泽他人”会激励包括我在内的不少读者在技术精进的道路上一路向前，同时去影响他人。2019-12-09Alex Liu 👍（1） 💬（1）才看到，真偶像2020-03-26fliaping 👍（1） 💬（1）这79块钱花的值2019-06-20uncle亮 👍（1） 💬（1）原来天下真有免费的午餐，哈哈唉2019-01-17潇洒 👍（1） 💬（1）赞，以自己的能力回馈社会，人生因为技术而变得更有价值，值得学习。2018-12-14dst 👍（0） 💬（1）自己的理想就是在照顾好家人都基础上，为社会做一些事情，目前还没到这个高度，恭喜华仔2024-08-08________未期 👍（0） 💬（1）优秀的人一定都有着优秀的品质👍🏻👍🏻2023-12-04Allan 👍（0） 💬（2）让技术既改变自己，也惠泽他人2023-03-30王奎-kevin 👍（0） 💬（1）华子厉害，达则兼济天下2022-07-20ifelse 👍（0） 💬（1）good2022-04-04</p>',7)])])}const m=r(_,[["render",n]]);export{f as __pageData,m as default};
